      "name": "speech",
      "type": "STRING",
      "description": "Speak in which the usuairio wants to get an answer",
      "default": "Hi"
    },
    {
      "name": "user",
      "type": "STRING",
      "description": "User who created the dialogue",
      "default": "5ec479048958430d6a6d5895"
    }
  ]
}

